  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 The Voice and Healthy Singing$j$, $j${"readings": [{"title": "Psalm 95 (King James Version)", "url": "/portal/bible/Psalms/95"}], "body": "The voice is the instrument every person carries. Singing begins with breath. Air from the lungs passes through the larynx, or voice box, where the vocal folds vibrate to make sound. The sound is shaped and made fuller by the throat, mouth and nose, which are called resonators, and by the tongue, lips and teeth, which shape words. This shaping is articulation, and clear articulation helps a congregation understand the words.\n\nGood singing begins with good posture. Stand tall with feet apart, shoulders relaxed, chin level and knees soft. Breathe low and deep so the belly and sides expand, and support the sound with steady air. Do not lift the shoulders. Sing with an open mouth and relaxed jaw, and think of the sound flowing forward.\n\nWarm up before you sing. Start with gentle humming, lip trills and slides on easy vowels, then sing simple scales, moving slowly up and down in comfortable ranges. Do not strain for high notes. Drink plenty of water, since the vocal folds work best when you are hydrated. Avoid shouting and screaming, and avoid whispering and clearing the throat harshly. If your voice is hoarse or sore, rest it. Pain is a signal to stop. Sleep and good health also help the voice. If a hoarse voice lasts more than two weeks, see a doctor.\n\nDuring the teen years voices change. Boys' voices drop as the larynx grows, and the voice may crack for a time. Girls' voices also change, often more gradually. Singers should sing in a comfortable range, and the choir director can help find the right part.\n\nPsalm 95:1 says, O come, let us sing unto the LORD: let us make a joyful noise to the rock of our salvation. A joyful noise can also be a well prepared one.\n\nYour task: (1) Explain how the voice makes sound. (2) List five habits of healthy singing. (3) Tell why a singer should rest the voice when it is sore.\n\nFlorida standards: MU.912.S.1, MU.912.S.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.S.1, MU.912.S.3", "script": "Welcome to Unit 5. Listen, you do not need to buy an instrument to make music. You already have one. Let us learn how to care for it.\n\nSinging begins with breath. Air from your lungs passes through the larynx, where the vocal folds vibrate to make sound. The throat, mouth and nose make the sound fuller. These are resonators. The tongue, lips and teeth shape the words. That is articulation, and clear words help a congregation understand.\n\nNow watch this. Good singing begins with posture. Stand tall, feet apart, shoulders relaxed, chin level, knees soft. Breathe low and deep so your belly and sides expand. Keep your jaw relaxed and your mouth open.\n\nLook at care. Warm up with gentle humming, lip trills and slides, then easy scales in a comfortable range. Do not strain for high notes. Drink plenty of water. Avoid shouting and harsh throat clearing. If your voice is hoarse or sore, rest it. Pain is a signal to stop. If hoarseness lasts more than two weeks, see a doctor.\n\nDuring the teen years voices change, and that is normal. Sing in a comfortable range and let your director help you find the right part.\n\nPsalm 95:1. O come, let us sing unto the LORD. A joyful noise can also be a well prepared one.\n\nYour task is to explain how the voice makes sound, list five healthy habits and explain why to rest a sore voice. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 The Voice and Healthy Singing$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Reading Music Notation$j$, $j${"readings": [{"title": "Exodus 31 (King James Version)", "url": "/portal/bible/Exodus/31"}], "body": "Notation is the written language of music. Notes are written on the staff, which has five lines and four spaces. The lines and spaces are counted from the bottom. A clef at the start of the staff tells which pitches the lines and spaces stand for. The treble clef is used for higher voices and instruments such as the violin, flute and right hand of the piano. The lines of the treble staff, from bottom to top, are E G B D F, which many students remember with the phrase Every Good Boy Does Fine. The spaces are F A C E, which spell the word face. The bass clef is used for lower voices and instruments such as the cello, tuba and left hand of the piano. Its lines, from bottom to top, are G B D F A, and its spaces are A C E G. Middle C sits between the two staffs. Short extra lines called ledger lines extend the staff.\n\nVertical bar lines divide the staff into measures. A time signature at the start tells how many beats are in each measure and which note gets one beat. A double bar marks the end of a section, and a final double bar marks the end of the piece. Sharps, flats and naturals change a pitch. A sharp raises a pitch by a half step, and a flat lowers it by a half step. A key signature, placed after the clef, shows which notes are sharp or flat throughout the piece. Dynamic and tempo marks tell how to perform it.\n\nReading music takes practice. Start by clapping rhythms and counting aloud, then add pitches. A hymnal is a good place to read. It shows four parts on two staffs, with soprano and alto together in the treble clef and tenor and bass together in the bass clef.\n\nExodus 31:3 says God filled Bezaleel with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship. Skill is a gift, and learning it is an act of stewardship.\n\nYour task: (1) Name the lines and spaces of the treble clef. (2) Explain bar lines, measures and time signatures. (3) Tell what a sharp, flat and key signature do.\n\nFlorida standards: MU.912.S.1, MU.912.O.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.S.1, MU.912.O.1", "script": "Welcome back. Listen, music has a written language, and once you learn it, you can read songs you have never heard.\n\nNotes are written on the staff, which has five lines and four spaces. A clef at the start tells which pitches the lines and spaces mean. The treble clef is for higher voices and instruments. Its lines are E G B D F, Every Good Boy Does Fine, and its spaces spell FACE. The bass clef is for lower voices and instruments. Its lines are G B D F A and its spaces are A C E G. Middle C sits between the two staffs.\n\nNow watch this. Bar lines divide the music into measures. The time signature tells how many beats are in each measure and which note gets the beat. A sharp raises a pitch by a half step. A flat lowers it by a half step. The key signature after the clef tells which notes are sharp or flat all the way through.\n\nLook at your hymnal. It shows four parts on two staffs. Soprano and alto share the treble clef. Tenor and bass share the bass clef. Start by clapping and counting rhythms, then add pitches.\n\nExodus 31:3. God filled Bezaleel with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship. Skill is a gift, and learning it is stewardship.\n\nYour task is to name the lines and spaces of the treble clef, explain measures and time signatures, and explain sharps, flats and key signatures. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Reading Music Notation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Singing and Playing Together$j$, $j${"readings": [{"title": "1 Corinthians 12 (King James Version)", "url": "/portal/bible/1Corinthians/12"}], "body": "Making music together is one of the best ways to learn it. A choir is a group of singers, usually divided into soprano, alto, tenor and bass. A band or orchestra is a group of instrumentalists. A small group of singers or players is an ensemble. A conductor leads a large group, using the hands to show the beat, tempo, dynamics, entrances and cutoffs.\n\nGood ensemble skills begin with listening. Listen to the people around you as well as to yourself. Blend your tone so no one voice sticks out. Match the vowel shapes and the dynamics of your section. Intonation means playing or singing in tune. Instrumentalists tune to a common pitch, and the standard tuning note is A at 440 vibrations per second. Balance means that parts are heard in the right proportion, so that the melody can be heard over the accompaniment. Keep your eyes on the conductor and follow the beat.\n\nRehearsal is practice as a group, and it needs good habits. Arrive on time with your music, a pencil and water. Mark the music with notes. Be quiet while the director is speaking. Practice difficult parts at home between rehearsals. Sectionals are rehearsals with one section only. Respect everyone, and help those who are learning.\n\nThe Bible speaks about unity. Psalm 133:1 says, Behold, how good and how pleasant it is for brethren to dwell together in unity! First Corinthians 12:12 says, For as the body is one, and hath many members, and all the members of that one body, being many, are one body. An ensemble is like the body of Christ. Each part has a role, and no part can say to another that it is not needed. Philippians 2:3 adds, Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves.\n\nYour task: (1) Define choir, ensemble and conductor. (2) Explain blend, intonation and balance. (3) Tell how an ensemble reflects First Corinthians 12:12.\n\nFlorida standards: MU.912.S.3, MU.912.C.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.S.3, MU.912.C.2", "script": "Welcome back. Listen, one voice is a gift. A hundred voices that blend are a miracle.\n\nA choir is a group of singers, usually soprano, alto, tenor and bass. A band or orchestra is a group of instrumentalists. A small group is an ensemble. A conductor leads, using the hands to show beat, tempo, dynamics, entrances and cutoffs.\n\nNow watch this. Good ensemble skills begin with listening. Listen to the people around you as well as yourself. Blend your tone so no one sticks out. Intonation means singing or playing in tune. Instrumentalists tune to a common pitch, and the standard tuning note is A at 440 vibrations per second. Balance means the parts are heard in the right proportion so the melody can be heard. Keep your eyes on the conductor.\n\nLook at rehearsal habits. Arrive on time with your music, a pencil and water. Mark your music. Be quiet when the director speaks. Practice hard parts at home. Respect everyone and help those who are learning.\n\nThe Bible speaks about unity. Psalm 133:1. Behold, how good and how pleasant it is for brethren to dwell together in unity! First Corinthians 12:12 compares the church to a body with many members. An ensemble is like that. Each part has a role. And Philippians 2:3 says, in lowliness of mind let each esteem other better than themselves.\n\nYour task is to define choir, ensemble and conductor, explain blend, intonation and balance, and explain First Corinthians 12:12. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Singing and Playing Together$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Practice, Performance and Hearing Protection$j$, $j${"readings": [{"title": "Isaiah 41 (King James Version)", "url": "/portal/bible/Isaiah/41"}], "body": "Skill grows through deliberate practice, which means focused work on specific goals. Short, regular sessions beat one long session. Practice a little each day. Begin with a warm up, then choose one or two problem spots. Slow the tempo until you can play it correctly, and use a metronome to speed it up gradually in small steps. Repeat the difficult measures instead of playing the whole piece from the start each time. Listen to yourself, and record a practice session to hear what you cannot hear while playing. Keep a practice journal with goals and results. Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings.\n\nPrepare for a performance by knowing the music well, practicing performing the whole piece, and practicing in the place if you can. Dress neatly and arrive early. Nerves are normal, and a little adrenaline can help. Breathe slowly, stand or sit tall, and think about the message and the listeners rather than yourself. Isaiah 41:10 says, Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee. If you make a mistake, keep going. Smile, bow or nod and thank the audience. In worship, remember that the aim is to serve God and help the congregation, not to impress people. Colossians 3:23 says to do it heartily, as to the Lord.\n\nProtect your hearing. Sound is measured in decibels. Long exposure to sound at or above about 85 decibels can damage hearing, and louder sounds do harm in a shorter time. Concerts, loud speakers, drums and headphones turned up high can all cause permanent hearing loss and ringing in the ears called tinnitus. Wear earplugs designed for music at loud events, keep headphones at a moderate volume, take listening breaks, and see a doctor if you notice ringing or muffled hearing.\n\nYour task: (1) List five practice habits that improve skill. (2) Describe how to prepare for and handle a performance. (3) Give four ways to protect your hearing.\n\nFlorida standards: MU.912.S.3, MU.912.C.2, MU.912.F.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.S.3, MU.912.C.2, MU.912.F.1", "script": "Welcome back. Listen, nobody becomes skilled by accident. Today we learn how to practice, perform and protect what God gave us.\n\nSkill grows through deliberate practice, focused work on specific goals. Short, regular sessions beat one long session. Warm up, then pick one or two problem spots. Slow the tempo until you can play it right, and use a metronome to speed up in small steps. Repeat the hard measures. Record yourself to hear what you cannot hear while playing. Keep a practice journal. Proverbs 22:29. Seest thou a man diligent in his business? he shall stand before kings.\n\nNow watch this. To prepare for a performance, know the music well and practice playing the whole piece through. Dress neatly and arrive early. Nerves are normal. Breathe slowly, sit or stand tall, and think about the message and the listeners rather than yourself. Isaiah 41:10. Fear thou not; for I am with thee. If you make a mistake, keep going. In worship the aim is to serve God and help the congregation. Colossians 3:23. Do it heartily, as to the Lord.\n\nLook at your hearing. Sound is measured in decibels. Long exposure at or above about 85 decibels can damage hearing. Concerts, loud speakers, drums and headphones turned up high can cause permanent hearing loss and ringing in the ears. Wear earplugs made for music at loud events, keep headphones at a moderate volume, take breaks, and see a doctor if you notice ringing or muffled hearing.\n\nYour task is to list five practice habits, describe how to prepare for a performance and give four ways to protect your hearing. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Practice, Performance and Hearing Protection$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Making Music, Skills and Performance$j$, $j${"prompt": "Write a report of at least 250 words on the skills of making music. Use complete sentences and label each part. Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings.\n\nPart 1: Explain how the voice makes sound and list five habits of healthy singing.\nPart 2: Draw or describe the staff, the treble clef lines and spaces, a measure, a time signature, a sharp and a flat.\nPart 3: Explain blend, intonation, balance and the role of the conductor in an ensemble.\nPart 4: Write a practice plan for two weeks with at least four practice habits and a goal. Keep a practice journal with at least six entries.\nPart 5: Record yourself or perform for a parent, guardian or teacher: sing or play a short song, hymn or rhythm. Describe what went well, what you would improve and how you protected your voice and hearing.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 15 points. Part 4: 20 points. Part 5: 25 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Making Music, Skills and Performance$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Practice and Humility$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells about a skill you have worked hard to improve and what helped you most, (2) explains how an ensemble teaches teamwork and humility, (3) describes how you handle nerves before speaking or performing, and (4) connects your answer to Philippians 2:3 or First Corinthians 12:12. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why should a musician protect his or her hearing and voice as a matter of stewardship? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Practice and Humility$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: The Voice and Healthy Singing$j$, $j${"questions": [{"q": "The vocal folds are in the:", "options": ["Larynx", "Stomach", "Ear", "Heart"]}, {"q": "Shaping words with the tongue, lips and teeth is called:", "options": ["Articulation", "Tempo", "Cadence", "Resonance"]}, {"q": "Which is a healthy habit for singers?", "options": ["Warming up and drinking water", "Singing through pain", "Shouting before a performance", "Whispering all day"]}, {"q": "If your voice is sore or hoarse, you should:", "options": ["Rest it", "Sing louder", "Scream", "Ignore it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Voice and Healthy Singing$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,0,0}'::int[], array[$j$The larynx holds the vocal folds, which vibrate to make sound.$j$,$j$Articulation makes words clear.$j$,$j$Warm ups and hydration protect the voice.$j$,$j$Pain is a signal to stop.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Voice and Healthy Singing$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Reading Music Notation$j$, $j${"questions": [{"q": "The spaces of the treble clef spell:", "options": ["BEAD", "CAGE", "FACE", "DEAF"]}, {"q": "A staff has:", "options": ["Three lines", "Eight lines", "Five lines and four spaces", "Four lines and five spaces"]}, {"q": "A sharp:", "options": ["Lowers a pitch by a half step", "Makes a note louder", "Ends a piece", "Raises a pitch by a half step"]}, {"q": "The lines that divide the staff into measures are called:", "options": ["Clefs", "Ledger lines", "Bar lines", "Tie lines"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Reading Music Notation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,2}'::int[], array[$j$The spaces from bottom to top are F A C E.$j$,$j$The staff has five lines and four spaces.$j$,$j$A flat lowers by a half step.$j$,$j$Bar lines mark off measures.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Reading Music Notation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Singing and Playing Together$j$, $j${"questions": [{"q": "Intonation means:", "options": ["Playing quickly", "Playing loudly", "Reading music", "Singing or playing in tune"]}, {"q": "The standard tuning note is A at:", "options": ["60 vibrations per second", "440 vibrations per second", "1000 vibrations per second", "100 vibrations per second"]}, {"q": "A conductor uses the hands to show:", "options": ["The price of tickets", "Beat, tempo, dynamics and entrances", "Only the words", "The key signature only"]}, {"q": "Psalm 133:1 describes the goodness of:", "options": ["Brethren dwelling together in unity", "Silence", "Travel", "Wealth"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Singing and Playing Together$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,0}'::int[], array[$j$Good intonation is accurate pitch.$j$,$j$Concert A is 440 hertz.$j$,$j$The conductor leads the ensemble.$j$,$j$Unity is a theme in worship.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Singing and Playing Together$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Practice, Performance and Hearing Protection$j$, $j${"questions": [{"q": "Deliberate practice means:", "options": ["Practicing only on the day of the concert", "Never repeating anything", "Focused work on specific goals", "Playing the whole piece loudly once"]}, {"q": "A good way to fix a hard measure is to:", "options": ["Skip it", "Slow it down and repeat it", "Avoid the metronome", "Play it louder"]}, {"q": "Long exposure to sound at or above about this level can damage hearing:", "options": ["10 decibels", "40 decibels", "20 decibels", "85 decibels"]}, {"q": "In worship, the aim of the musician is to:", "options": ["Be the loudest", "Impress the audience", "Be noticed", "Serve God and help the congregation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Practice, Performance and Hearing Protection$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,3}'::int[], array[$j$Targeted practice builds skill fastest.$j$,$j$Slow, repeated practice builds accuracy.$j$,$j$Loud sound over time harms the ears.$j$,$j$Worship is for God's glory.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Practice, Performance and Hearing Protection$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Making Music, Skills and Performance$j$, $j${"questions": [{"q": "The vocal folds vibrate in the:", "options": ["Lungs", "Larynx", "Ear", "Nose"]}, {"q": "A good singing posture is:", "options": ["Slouching", "Standing tall with relaxed shoulders", "Raising the shoulders", "Locking the knees"]}, {"q": "The lines of the bass clef from bottom to top are:", "options": ["A C E G", "E G B D F", "F A C E", "G B D F A"]}, {"q": "A flat:", "options": ["Raises a pitch by a half step", "Makes music louder", "Lowers a pitch by a half step", "Ends a piece"]}, {"q": "A time signature tells:", "options": ["The loudness", "The name of the piece", "The composer", "How many beats are in a measure and which note gets one beat"]}, {"q": "Balance in an ensemble means:", "options": ["No one listens", "Only the soloist plays", "Parts are heard in the right proportion", "Everyone plays as loudly as possible"]}, {"q": "Practicing a hard passage slowly and repeating it is:", "options": ["Only for beginners", "Cheating", "A waste of time", "Deliberate practice"]}, {"q": "Wearing earplugs at loud concerts helps prevent:", "options": ["Rehearsal", "Tuning", "Hearing loss", "Singing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Making Music, Skills and Performance$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,2,3,2,3,2}'::int[], array[$j$The larynx is the voice box.$j$,$j$Posture supports breath.$j$,$j$The bass clef lines are G B D F A.$j$,$j$A flat lowers a pitch.$j$,$j$The time signature sets the meter.$j$,$j$Balance lets the melody be heard.$j$,$j$Slow repetition builds accuracy.$j$,$j$Protect your hearing.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Making Music, Skills and Performance$j$ on conflict (item_id) do nothing;
